package main

import (
	"fmt"
)

func main() {
	var n, m, a, b int
	fmt.Scan(&n, &m, &a, &b)

	// Option 1: Buy only single tickets
	option1 := n * a

	// Option 2: Buy enough m-ride tickets to cover all rides
	fullTickets := n / m
	remainder := n % m
	option2 := fullTickets * b
	if remainder > 0 {
		option2 += b
	}

	// Option 3: Buy full m-ride tickets and single tickets for the remainder
	option3 := fullTickets * b
	if remainder > 0 {
		option3 += remainder * a
	}

	// Find the minimum of all options
	minCost := option1
	if option2 < minCost {
		minCost = option2
	}
	if option3 < minCost {
		minCost = option3
	}

	fmt.Println(minCost)
}
