package main

import (
	"fmt"
)

func main() {
	var n, m, a, b int
	fmt.Scan(&n, &m, &a, &b)

	// Number of full m-ride tickets needed
	full := n / m
	// Remaining rides after using full m-ride tickets
	remainder := n % m

	// Cost using full m-ride tickets plus single tickets for remainder
	cost1 := full*b + remainder*a

	// Cost using one extra m-ride ticket to cover remainder (if any)
	cost2 := (full + 1) * b

	// Cost using only single tickets
	cost3 := n * a

	// Find the minimum of the three options
	minCost := cost1
	if cost2 < minCost {
		minCost = cost2
	}
	if cost3 < minCost {
		minCost = cost3
	}

	fmt.Println(minCost)
}
